css:
.print-format {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 9px;
    color: #17212b;
}
.dlhr .report-heading {
    border-bottom: 2px solid #263746;
    padding-bottom: 9px;
    margin-bottom: 14px;
}
.dlhr h2 {
    font-size: 20px;
    font-weight: 700;
    margin: 0 0 4px;
}
.dlhr .reference {
    margin-top: 5px;
    color: #52606d;
}
.dlhr .status {
    margin-top: 5px;
    font-weight: bold;
    letter-spacing: 2px;
}
.dlhr h3 {
    font-size: 11px;
    font-weight: 700;
    margin: 16px 0 7px;
    page-break-after: avoid;
}
.dlhr table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 10px;
}
.dlhr table th,
.dlhr table td {
    border: 1px solid #687581 !important;
    padding: 6px 5px !important;
    vertical-align: top !important;
    line-height: 1.4;
    overflow-wrap: break-word;
    word-wrap: break-word;
    color: #17212b !important;
}
.dlhr table th {
    background: #e7edf2 !important;
    font-weight: 700;
}
.dlhr .details th {
    width: 20%;
}
.dlhr .details td {
    width: 30%;
}
.dlhr thead {
    display: table-header-group;
}
.dlhr tr {
    page-break-inside: avoid;
}
.dlhr .number {
    text-align: right;
    white-space: nowrap;
}
.dlhr .centre,
.dlhr .time {
    text-align: center;
}
.dlhr .time {
    font-size: 8px;
}
.dlhr .multiline,
.dlhr .comments {
    white-space: pre-wrap;
}
.dlhr .total-row td {
    background: #e7edf2 !important;
    font-weight: bold;
}
.dlhr .emphasis {
    font-weight: bold;
}
.dlhr .note {
    font-size: 8px;
    color: #52606d;
    margin-top: 7px;
}
.dlhr .comments {
    border: 1px solid #687581;
    padding: 9px;
    line-height: 1.5;
    overflow-wrap: break-word;
}
@media print {
    .dlhr table th,
    .dlhr .total-row td {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}

.dlhr .report-subtitle {
    font-size: 13px;
    font-weight: 600;
    margin-top: 5px;
    line-height: 1.4;
}
